//! TLS under any stream protocol: HTTPS is TLS + HTTP, DNS over TLS is TLS +
//! DNS.
//!
//! The handshakes are real ([rustls]): TLS 1.2 and 1.3 with the versions,
//! cipher suites, key exchange groups and ALPN protocols a profile picks,
//! server certificates from files or generated by a lab CA, client
//! certificates (mutual TLS), session resumption, and the application data
//! encrypted for real, so either end works against real software (`curl`,
//! browsers, nginx, `openssl s_server`).
//!
//! [`Tls`] wraps another [`App`]: its sessions run the handshake, then hand
//! the inner protocol's session the decrypted bytes and encrypt what it
//! sends. Each handshake is counted ([`AppHandshake`]): what it negotiated or
//! why it failed, whether it resumed a session, how long it took. A profile
//! can expect handshakes to fail (`expect = "failure"`), for testing that a
//! server refuses an old version or a client without a certificate.

use std::fmt;
use std::io::{Read, Write};
use std::sync::Arc;
use std::time::Duration;

use rustls::client::danger::{HandshakeSignatureValid, ServerCertVerified, ServerCertVerifier};
use rustls::client::{Resumption, WebPkiServerVerifier};
use rustls::crypto::{CryptoProvider, SupportedKxGroup};
use rustls::pki_types::pem::PemObject;
use rustls::pki_types::{CertificateDer, PrivateKeyDer, ServerName, UnixTime};
use rustls::server::{NoServerSessionStorage, WebPkiClientVerifier};
use rustls::{
    ClientConfig, Connection, DigitallySignedStruct, RootCertStore, ServerConfig, SignatureScheme,
    SupportedCipherSuite, SupportedProtocolVersion,
};

use super::Transport;
use super::{App, AppCx, AppHandshake, AppProtocol, AppRole, AppSession, Receive, SessionInit};
use crate::{Error, Result};

fn err(m: impl fmt::Display) -> Error {
    Error::Profile(m.to_string())
}

/// A TLS version a profile can pick.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum TlsVersion {
    Tls12,
    Tls13,
}

impl TlsVersion {
    fn rustls(self) -> &'static SupportedProtocolVersion {
        match self {
            TlsVersion::Tls12 => &rustls::version::TLS12,
            TlsVersion::Tls13 => &rustls::version::TLS13,
        }
    }
}

impl std::str::FromStr for TlsVersion {
    type Err = Error;
    fn from_str(s: &str) -> Result<Self> {
        let t = s.trim().to_ascii_lowercase().replace(['v', '_', ' '], "");
        match t.trim_start_matches("tls") {
            "1.2" | "12" => Ok(TlsVersion::Tls12),
            "1.3" | "13" => Ok(TlsVersion::Tls13),
            "1.0" | "10" | "1.1" | "11" | "1" | "ssl3" | "ssl3.0" => Err(err(format!(
                "TLS version `{s}` is not supported: only 1.2 and 1.3 (old versions are insecure and rustls does not speak them)"
            ))),
            _ => Err(err(format!("unknown TLS version `{s}`; use 1.2 or 1.3"))),
        }
    }
}

impl fmt::Display for TlsVersion {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            TlsVersion::Tls12 => "1.2",
            TlsVersion::Tls13 => "1.3",
        })
    }
}

/// The key type of generated certificates.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum KeyType {
    #[default]
    EcdsaP256,
    EcdsaP384,
    Ed25519,
}

impl KeyType {
    fn alg(self) -> &'static rcgen::SignatureAlgorithm {
        match self {
            KeyType::EcdsaP256 => &rcgen::PKCS_ECDSA_P256_SHA256,
            KeyType::EcdsaP384 => &rcgen::PKCS_ECDSA_P384_SHA384,
            KeyType::Ed25519 => &rcgen::PKCS_ED25519,
        }
    }
}

impl std::str::FromStr for KeyType {
    type Err = Error;
    fn from_str(s: &str) -> Result<Self> {
        match s.to_ascii_lowercase().replace(['_', ' '], "-").as_str() {
            "ecdsa" | "ecdsa-p256" | "p256" | "p-256" => Ok(KeyType::EcdsaP256),
            "ecdsa-p384" | "p384" | "p-384" => Ok(KeyType::EcdsaP384),
            "ed25519" => Ok(KeyType::Ed25519),
            "rsa" => Err(err(
                "generated RSA keys are not supported: give an RSA `cert` and `key` (e.g. from openssl)",
            )),
            _ => Err(err(format!(
                "unknown key type `{s}`; use ecdsa-p256, ecdsa-p384 or ed25519"
            ))),
        }
    }
}

/// Whether the server asks clients for a certificate.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum ClientAuth {
    #[default]
    None,
    Optional,
    Required,
}

impl std::str::FromStr for ClientAuth {
    type Err = Error;
    fn from_str(s: &str) -> Result<Self> {
        match s.to_ascii_lowercase().as_str() {
            "none" | "off" | "no" => Ok(ClientAuth::None),
            "optional" | "request" => Ok(ClientAuth::Optional),
            "required" | "require" | "yes" => Ok(ClientAuth::Required),
            _ => Err(err(format!(
                "unknown client_auth `{s}`; use none, optional or required"
            ))),
        }
    }
}

/// A certificate chain and its key, PEM.
#[derive(Clone, PartialEq, Eq)]
pub struct CertKey {
    pub chain: Vec<u8>,
    pub key: Vec<u8>,
}

impl fmt::Debug for CertKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "CertKey({} bytes of chain)", self.chain.len())
    }
}

impl CertKey {
    fn parse(&self, what: &str) -> Result<(Vec<CertificateDer<'static>>, PrivateKeyDer<'static>)> {
        let chain = certs(&self.chain, what)?;
        let key = PrivateKeyDer::from_pem_slice(&self.key)
            .map_err(|e| err(format!("{what} key: {e}")))?;
        Ok((chain, key))
    }
}

/// The TLS settings of one end. [`Tls::new`] takes one for each, so the
/// client can offer what the server refuses.
#[derive(Clone, Debug, PartialEq)]
pub struct TlsSettings {
    /// The versions this end speaks; empty for 1.2 and 1.3.
    pub versions: Vec<TlsVersion>,
    /// Cipher suites by name (`TLS13_AES_128_GCM_SHA256`,
    /// `TLS_ECDHE_ECDSA_WITH_AES_128_GCM_SHA256`), in order of preference;
    /// empty for rustls's own list.
    pub cipher_suites: Vec<String>,
    /// Key exchange groups (`X25519`, `secp256r1`, `secp384r1`); empty for all.
    pub groups: Vec<String>,
    /// ALPN protocols (`http/1.1`, `h2`), in order of preference.
    pub alpn: Vec<String>,
    /// Client: the name it asks for (SNI) and checks the certificate
    /// against; none for the address it connects to (no SNI sent).
    pub server_name: Option<String>,
    /// Client: check the server's certificate (against `ca`, else the
    /// generated lab CA).
    pub verify: bool,
    /// Client: the CAs it trusts (PEM).
    pub ca: Option<Vec<u8>>,
    /// Server: its certificate and key; none for one the lab CA issues.
    pub cert: Option<CertKey>,
    /// Server: the names in a generated certificate (DNS names or addresses).
    pub names: Vec<String>,
    /// The key type of generated certificates.
    pub key_type: KeyType,
    /// Server: ask clients for a certificate. Client: present one (its
    /// `client_cert`, else one the lab CA issues).
    pub client_auth: ClientAuth,
    /// Server: the CAs client certificates must come from (PEM); none for
    /// the lab CA.
    pub client_ca: Option<Vec<u8>>,
    /// Client: its certificate and key.
    pub client_cert: Option<CertKey>,
    /// Resume sessions (tickets, session ids) on later connections.
    pub resumption: bool,
    /// Handshakes are expected to fail.
    pub expect_failure: bool,
}

impl Default for TlsSettings {
    fn default() -> Self {
        Self {
            versions: Vec::new(),
            cipher_suites: Vec::new(),
            groups: Vec::new(),
            alpn: Vec::new(),
            server_name: None,
            verify: false,
            ca: None,
            cert: None,
            names: vec!["ferotrx.lab".into()],
            key_type: KeyType::default(),
            client_auth: ClientAuth::None,
            client_ca: None,
            client_cert: None,
            resumption: true,
            expect_failure: false,
        }
    }
}

impl TlsSettings {
    fn versions_text(&self) -> String {
        let mut v = self.versions.clone();
        if v.is_empty() {
            v = vec![TlsVersion::Tls12, TlsVersion::Tls13];
        }
        v.sort();
        v.dedup();
        v.iter()
            .map(|v| v.to_string())
            .collect::<Vec<_>>()
            .join("/")
    }

    /// Versions, suites and groups: what both ends must agree on.
    fn offer(&self) -> String {
        let mut s = format!("TLS {}", self.versions_text());
        if !self.cipher_suites.is_empty() {
            s += &format!(" {}", self.cipher_suites.join(","));
        }
        if !self.groups.is_empty() {
            s += &format!(" groups {}", self.groups.join(","));
        }
        s
    }
}

/// `TLS 1.3, verified, SNI www.lab.local, client certificates required`.
fn summary(client: &TlsSettings, server: &TlsSettings) -> String {
    let (c, sv) = (client.offer(), server.offer());
    let mut s = if c == sv {
        c
    } else {
        format!("{c} (server {})", sv.trim_start_matches("TLS "))
    };
    if client.verify {
        s += ", verified";
    }
    if let Some(n) = &client.server_name {
        s += &format!(", SNI {n}");
    }
    match server.client_auth {
        ClientAuth::None if client.client_auth != ClientAuth::None => s += ", client certificate",
        ClientAuth::None => {}
        ClientAuth::Optional => s += ", client certificates optional",
        ClientAuth::Required => s += ", client certificates required",
    }
    if client.expect_failure || server.expect_failure {
        s += ", expected to fail";
    }
    s
}

/// TLS under another stream protocol; see the [module](self) docs.
pub struct Tls {
    inner: App,
    client: TlsSettings,
    server: TlsSettings,
    client_config: Arc<ClientConfig>,
    server_config: Arc<ServerConfig>,
}

impl fmt::Debug for Tls {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Tls")
            .field("inner", &self.inner)
            .field("client", &self.client)
            .field("server", &self.server)
            .finish()
    }
}

impl Tls {
    /// TLS with the same settings at both ends under `inner`.
    pub fn new(inner: App, settings: TlsSettings) -> Result<Self> {
        Self::with_ends(inner, settings.clone(), settings)
    }

    /// TLS with settings for each end under `inner`.
    pub fn with_ends(inner: App, client: TlsSettings, server: TlsSettings) -> Result<Self> {
        if !inner.supports(Transport::Stream) {
            return Err(err(format!(
                "TLS runs under stream protocols; {} does not run over TCP",
                inner.name()
            )));
        }
        let lab = LabCa::new(client.key_type)?;
        let client_config = Arc::new(client_config(&client, &lab)?);
        let server_config = Arc::new(server_config(&server, &lab)?);
        Ok(Self {
            inner,
            client,
            server,
            client_config,
            server_config,
        })
    }

    /// The protocol on top.
    pub fn inner(&self) -> &App {
        &self.inner
    }

    pub fn client_settings(&self) -> &TlsSettings {
        &self.client
    }

    pub fn server_settings(&self) -> &TlsSettings {
        &self.server
    }
}

impl AppProtocol for Tls {
    fn name(&self) -> &str {
        match self.inner.name() {
            "http" => "https",
            "http2" => "h2",
            _ => "tls",
        }
    }

    fn describe(&self) -> String {
        format!(
            "{} + {}",
            summary(&self.client, &self.server),
            self.inner.describe()
        )
    }

    fn default_port(&self) -> u16 {
        match self.inner.name() {
            "http" | "http2" => 443,
            "dns" => 853,
            "mqtt" => 8883,
            _ => self.inner.default_port(),
        }
    }

    fn supports(&self, transport: Transport) -> bool {
        transport == Transport::Stream
    }

    fn validate(&self, role: AppRole, transport: Transport) -> Result<()> {
        self.inner.validate(role, transport)
    }

    fn session(&self, init: &SessionInit) -> Box<dyn AppSession> {
        let inner = self.inner.session(init);
        let conn = match init.role {
            AppRole::Client => None,
            AppRole::Server => Some(
                rustls::ServerConnection::new(self.server_config.clone()).map(Connection::Server),
            ),
        };
        let settings = match init.role {
            AppRole::Client => &self.client,
            AppRole::Server => &self.server,
        };
        let server_name = match &self.client.server_name {
            Some(n) => ServerName::try_from(n.clone()).ok(),
            None => Some(ServerName::IpAddress(init.remote.ip().into())),
        };
        Box::new(TlsSession {
            conn: conn.map(|c| c.map_err(|e| e.to_string())),
            inner,
            role: init.role,
            client_config: self.client_config.clone(),
            server_name,
            expect_failure: settings.expect_failure,
            began: None,
            state: State::Handshaking,
            inner_told_closed: false,
            peer_done: false,
            buf: vec![0; 16 * 1024],
        })
    }

    fn as_any(&self) -> &dyn std::any::Any {
        self
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum State {
    Handshaking,
    Open,
    Failed,
}

struct TlsSession {
    /// The server's connection from the start; the client's from `start`.
    conn: Option<std::result::Result<Connection, String>>,
    inner: Box<dyn AppSession>,
    role: AppRole,
    client_config: Arc<ClientConfig>,
    server_name: Option<ServerName<'static>>,
    expect_failure: bool,
    began: Option<Duration>,
    state: State,
    inner_told_closed: bool,
    /// The other end sent close_notify or closed the connection: it reads
    /// nothing more, so no close_notify goes back (a closed socket would
    /// answer it with a reset).
    peer_done: bool,
    buf: Vec<u8>,
}

impl TlsSession {
    /// Sends what rustls has to send.
    fn flush(&mut self, cx: &mut AppCx) {
        let Some(Ok(conn)) = &mut self.conn else {
            return;
        };
        while conn.wants_write() {
            let mut out = Vec::new();
            if conn.write_tls(&mut out).is_err() || out.is_empty() {
                break;
            }
            cx.send(out);
        }
    }

    /// The handshake failed (or the connection broke later): count it, send
    /// the alert rustls has queued, and close.
    fn fail(&mut self, cx: &mut AppCx, why: String) {
        match self.state {
            State::Handshaking => cx.handshake(AppHandshake {
                label: format!("failed: {why}"),
                succeeded: false,
                expected: self.expect_failure,
                resumed: false,
                time: self.began.map(|b| cx.now().saturating_sub(b)),
            }),
            State::Open => cx.protocol_error(format!("TLS: {why}")),
            State::Failed => {}
        }
        self.state = State::Failed;
        self.flush(cx);
        cx.close();
    }

    /// Runs `f` on the inner session; what it sends goes out encrypted.
    fn inner_call(&mut self, cx: &mut AppCx, f: impl FnOnce(&mut dyn AppSession, &mut AppCx)) {
        let mut icx = AppCx::new(cx.now(), cx.wall());
        f(&mut *self.inner, &mut icx);
        let close = icx.wants_close();
        let sends = cx.absorb(icx);
        let Some(Ok(conn)) = &mut self.conn else {
            return;
        };
        for d in sends {
            // rustls takes only so much plaintext at a time: hand it over
            // in pieces and send the records in between.
            let mut rest = &d[..];
            while !rest.is_empty() {
                match conn.writer().write(rest) {
                    Ok(n) if n > 0 => rest = &rest[n..],
                    _ => {
                        if !conn.wants_write() {
                            break;
                        }
                    }
                }
                while conn.wants_write() {
                    let mut out = Vec::new();
                    if conn.write_tls(&mut out).is_err() || out.is_empty() {
                        break;
                    }
                    cx.send(out);
                }
            }
        }
        if close && !self.peer_done {
            conn.send_close_notify();
        }
    }

    /// After rustls took records: the end of the handshake, then the
    /// plaintext for the inner session.
    fn after_records(&mut self, cx: &mut AppCx) {
        let Some(Ok(conn)) = &mut self.conn else {
            return;
        };
        if self.state == State::Handshaking && !conn.is_handshaking() {
            let version = match conn.protocol_version() {
                Some(rustls::ProtocolVersion::TLSv1_2) => "TLSv1.2".to_string(),
                Some(rustls::ProtocolVersion::TLSv1_3) => "TLSv1.3".to_string(),
                Some(v) => format!("{v:?}"),
                None => "TLS".to_string(),
            };
            let suite = conn
                .negotiated_cipher_suite()
                .map(|s| format!(" {:?}", s.suite()))
                .unwrap_or_default();
            let alpn = conn
                .alpn_protocol()
                .map(|p| format!(" {}", String::from_utf8_lossy(p)))
                .unwrap_or_default();
            let resumed = conn.handshake_kind() == Some(rustls::HandshakeKind::Resumed);
            cx.handshake(AppHandshake {
                label: format!("{version}{suite}{alpn}"),
                succeeded: true,
                expected: !self.expect_failure,
                resumed,
                time: self.began.map(|b| cx.now().saturating_sub(b)),
            });
            self.state = State::Open;
            self.inner_call(cx, |s, icx| s.start(icx));
        }
        if self.state != State::Open {
            return;
        }
        loop {
            let Some(Ok(conn)) = &mut self.conn else {
                return;
            };
            match conn.reader().read(&mut self.buf) {
                Ok(0) => {
                    // close_notify: the other end is done.
                    self.peer_done = true;
                    if !self.inner_told_closed {
                        self.inner_told_closed = true;
                        self.inner_call(cx, |s, icx| s.peer_closed(icx));
                    }
                    return;
                }
                Ok(n) => {
                    let data = self.buf[..n].to_vec();
                    let mut not_mine = false;
                    self.inner_call(cx, |s, icx| {
                        not_mine = s.receive(&data, icx) == Receive::NotMine;
                    });
                    if not_mine {
                        cx.protocol_error("bytes the protocol does not take");
                        cx.close();
                        return;
                    }
                }
                Err(_) => return,
            }
        }
    }
}

impl AppSession for TlsSession {
    fn start(&mut self, cx: &mut AppCx) {
        self.began = Some(cx.now());
        if self.role != AppRole::Client {
            return;
        }
        let r = match self.server_name.clone() {
            Some(name) => rustls::ClientConnection::new(self.client_config.clone(), name)
                .map(Connection::Client)
                .map_err(|e| e.to_string()),
            None => Err("no valid server name".to_string()),
        };
        match r {
            Ok(c) => {
                self.conn = Some(Ok(c));
                self.flush(cx);
            }
            Err(e) => {
                self.conn = Some(Err(e.clone()));
                self.fail(cx, e);
            }
        }
    }

    fn receive(&mut self, data: &[u8], cx: &mut AppCx) -> Receive {
        if self.state == State::Failed {
            return Receive::Taken;
        }
        if self.began.is_none() {
            self.began = Some(cx.now());
        }
        if let Some(Err(e)) = &self.conn {
            let e = e.clone();
            self.fail(cx, e);
            return Receive::Taken;
        }
        let mut rd = data;
        while !rd.is_empty() {
            let Some(Ok(conn)) = &mut self.conn else {
                break;
            };
            match conn.read_tls(&mut rd) {
                Ok(0) => break,
                Ok(_) => {}
                Err(e) => {
                    self.fail(cx, e.to_string());
                    return Receive::Taken;
                }
            }
            if let Err(e) = conn.process_new_packets() {
                self.fail(cx, failure(&e));
                return Receive::Taken;
            }
            self.after_records(cx);
            if self.state == State::Failed {
                return Receive::Taken;
            }
        }
        self.flush(cx);
        Receive::Taken
    }

    fn peer_closed(&mut self, cx: &mut AppCx) {
        self.peer_done = true;
        match self.state {
            State::Handshaking => self.fail(cx, "closed during the handshake".into()),
            State::Open => {
                if !self.inner_told_closed {
                    self.inner_told_closed = true;
                    self.inner_call(cx, |s, icx| s.peer_closed(icx));
                }
                self.flush(cx);
            }
            State::Failed => {}
        }
    }

    fn timer(&mut self, cx: &mut AppCx) {
        if self.state == State::Open {
            self.inner_call(cx, |s, icx| s.timer(icx));
            self.flush(cx);
        }
    }
}

/// Why a handshake failed, short: `alert HandshakeFailure`, `bad
/// certificate: UnknownIssuer`.
fn failure(e: &rustls::Error) -> String {
    use rustls::Error as E;
    match e {
        E::AlertReceived(a) => format!("alert {a:?}"),
        E::InvalidCertificate(c) => format!("bad certificate: {c:?}"),
        E::PeerIncompatible(p) => format!("incompatible: {p:?}"),
        E::PeerMisbehaved(p) => format!("misbehaved: {p:?}"),
        E::NoCertificatesPresented => "no certificate presented".into(),
        E::NoApplicationProtocol => "no common ALPN protocol".into(),
        e => e.to_string(),
    }
}

// ---- configurations -------------------------------------------------------

fn certs(pem: &[u8], what: &str) -> Result<Vec<CertificateDer<'static>>> {
    let list = CertificateDer::pem_slice_iter(pem)
        .collect::<std::result::Result<Vec<_>, _>>()
        .map_err(|e| err(format!("{what}: {e}")))?;
    if list.is_empty() {
        return Err(err(format!("{what}: no certificate in it")));
    }
    Ok(list)
}

fn roots(pem: &[u8], what: &str) -> Result<RootCertStore> {
    let mut store = RootCertStore::empty();
    for c in certs(pem, what)? {
        store.add(c).map_err(|e| err(format!("{what}: {e}")))?;
    }
    Ok(store)
}

/// The name of a cipher suite, without `TLS_`/`TLS13_` and case, for matching.
fn suite_key(s: &str) -> String {
    s.to_ascii_uppercase()
        .replace('-', "_")
        .trim_start_matches("TLS13_")
        .trim_start_matches("TLS_")
        .to_string()
}

/// The names of the cipher suites rustls has.
pub fn cipher_suite_names() -> Vec<String> {
    rustls::crypto::ring::ALL_CIPHER_SUITES
        .iter()
        .map(|s| format!("{:?}", s.suite()))
        .collect()
}

/// The names of the key exchange groups rustls has.
pub fn group_names() -> Vec<String> {
    rustls::crypto::ring::ALL_KX_GROUPS
        .iter()
        .map(|g| format!("{:?}", g.name()))
        .collect()
}

fn provider(s: &TlsSettings) -> Result<CryptoProvider> {
    let mut p = rustls::crypto::ring::default_provider();
    if !s.cipher_suites.is_empty() {
        let mut list: Vec<SupportedCipherSuite> = Vec::new();
        for name in &s.cipher_suites {
            let want = suite_key(name);
            let suite = rustls::crypto::ring::ALL_CIPHER_SUITES
                .iter()
                .find(|c| suite_key(&format!("{:?}", c.suite())) == want)
                .ok_or_else(|| {
                    err(format!(
                        "unknown cipher suite `{name}`; known: {}",
                        cipher_suite_names().join(", ")
                    ))
                })?;
            list.push(*suite);
        }
        p.cipher_suites = list;
    }
    if !s.groups.is_empty() {
        let mut list: Vec<&'static dyn SupportedKxGroup> = Vec::new();
        for name in &s.groups {
            let want = name.to_ascii_lowercase().replace('-', "");
            let g = rustls::crypto::ring::ALL_KX_GROUPS
                .iter()
                .find(|g| {
                    let n = format!("{:?}", g.name()).to_ascii_lowercase();
                    n == want
                        || (want == "p256" && n == "secp256r1")
                        || (want == "p384" && n == "secp384r1")
                })
                .ok_or_else(|| {
                    err(format!(
                        "unknown key exchange group `{name}`; known: {}",
                        group_names().join(", ")
                    ))
                })?;
            list.push(*g);
        }
        p.kx_groups = list;
    }
    Ok(p)
}

fn versions(s: &TlsSettings) -> Vec<&'static SupportedProtocolVersion> {
    if s.versions.is_empty() {
        vec![&rustls::version::TLS13, &rustls::version::TLS12]
    } else {
        let mut v = s.versions.clone();
        v.sort();
        v.dedup();
        v.iter().rev().map(|v| v.rustls()).collect()
    }
}

fn check_suites(s: &TlsSettings, p: &CryptoProvider) -> Result<()> {
    let vs = versions(s);
    if !p
        .cipher_suites
        .iter()
        .any(|c| vs.iter().any(|v| c.version() == *v))
    {
        return Err(err(format!(
            "none of the cipher suites is for TLS {}",
            s.versions_text()
        )));
    }
    Ok(())
}

fn client_config(s: &TlsSettings, lab: &LabCa) -> Result<ClientConfig> {
    let p = Arc::new(provider(s)?);
    check_suites(s, &p)?;
    let b = ClientConfig::builder_with_provider(p.clone())
        .with_protocol_versions(&versions(s))
        .map_err(|e| err(format!("TLS: {e}")))?;
    let b = if s.verify {
        let store = match &s.ca {
            Some(pem) => roots(pem, "ca")?,
            None => roots(lab.ca_pem.as_bytes(), "lab CA")?,
        };
        let v = WebPkiServerVerifier::builder_with_provider(Arc::new(store), p.clone())
            .build()
            .map_err(|e| err(format!("ca: {e}")))?;
        b.with_webpki_verifier(v)
    } else {
        b.dangerous()
            .with_custom_certificate_verifier(Arc::new(AcceptAny(p.clone())))
    };
    let mut c = match (&s.client_cert, s.client_auth) {
        (Some(ck), _) => {
            let (chain, key) = ck.parse("client_cert")?;
            b.with_client_auth_cert(chain, key)
                .map_err(|e| err(format!("client_cert: {e}")))?
        }
        (None, ClientAuth::None) => b.with_no_client_auth(),
        (None, _) => {
            let (chain, key) = lab.issue(&[], true, s.key_type)?.parse("lab client")?;
            b.with_client_auth_cert(chain, key)
                .map_err(|e| err(format!("lab client certificate: {e}")))?
        }
    };
    c.alpn_protocols = s.alpn.iter().map(|a| a.as_bytes().to_vec()).collect();
    if !s.resumption {
        c.resumption = Resumption::disabled();
    }
    Ok(c)
}

fn server_config(s: &TlsSettings, lab: &LabCa) -> Result<ServerConfig> {
    let p = Arc::new(provider(s)?);
    check_suites(s, &p)?;
    let b = ServerConfig::builder_with_provider(p.clone())
        .with_protocol_versions(&versions(s))
        .map_err(|e| err(format!("TLS: {e}")))?;
    let b = match s.client_auth {
        ClientAuth::None => b.with_no_client_auth(),
        a => {
            let store = match &s.client_ca {
                Some(pem) => roots(pem, "client_ca")?,
                None => roots(lab.ca_pem.as_bytes(), "lab CA")?,
            };
            let mut vb = WebPkiClientVerifier::builder_with_provider(Arc::new(store), p.clone());
            if a == ClientAuth::Optional {
                vb = vb.allow_unauthenticated();
            }
            b.with_client_cert_verifier(vb.build().map_err(|e| err(format!("client_ca: {e}")))?)
        }
    };
    let (chain, key) = match &s.cert {
        Some(ck) => ck.parse("cert")?,
        None => lab
            .issue(&s.names, false, s.key_type)?
            .parse("lab server")?,
    };
    let mut c = b
        .with_single_cert(chain, key)
        .map_err(|e| err(format!("cert: {e}")))?;
    c.alpn_protocols = s.alpn.iter().map(|a| a.as_bytes().to_vec()).collect();
    if !s.resumption {
        c.session_storage = Arc::new(NoServerSessionStorage {});
        c.send_tls13_tickets = 0;
    }
    Ok(c)
}

/// The rustls configurations of both ends, with a lab CA of their own for
/// what the settings leave out (for QUIC, which drives rustls itself).
pub(crate) fn configs(
    client: &TlsSettings,
    server: &TlsSettings,
) -> Result<(ClientConfig, ServerConfig)> {
    let lab = LabCa::new(client.key_type)?;
    Ok((client_config(client, &lab)?, server_config(server, &lab)?))
}

/// A client that takes any server certificate (`verify = false`), still
/// checking the handshake signatures.
#[derive(Debug)]
struct AcceptAny(Arc<CryptoProvider>);

impl ServerCertVerifier for AcceptAny {
    fn verify_server_cert(
        &self,
        _end_entity: &CertificateDer<'_>,
        _intermediates: &[CertificateDer<'_>],
        _server_name: &ServerName<'_>,
        _ocsp_response: &[u8],
        _now: UnixTime,
    ) -> std::result::Result<ServerCertVerified, rustls::Error> {
        Ok(ServerCertVerified::assertion())
    }

    fn verify_tls12_signature(
        &self,
        message: &[u8],
        cert: &CertificateDer<'_>,
        dss: &DigitallySignedStruct,
    ) -> std::result::Result<HandshakeSignatureValid, rustls::Error> {
        rustls::crypto::verify_tls12_signature(
            message,
            cert,
            dss,
            &self.0.signature_verification_algorithms,
        )
    }

    fn verify_tls13_signature(
        &self,
        message: &[u8],
        cert: &CertificateDer<'_>,
        dss: &DigitallySignedStruct,
    ) -> std::result::Result<HandshakeSignatureValid, rustls::Error> {
        rustls::crypto::verify_tls13_signature(
            message,
            cert,
            dss,
            &self.0.signature_verification_algorithms,
        )
    }

    fn supported_verify_schemes(&self) -> Vec<SignatureScheme> {
        self.0.signature_verification_algorithms.supported_schemes()
    }
}

/// A CA made for one profile, which issues the certificates a profile does
/// not give.
struct LabCa {
    ca_pem: String,
    issuer: rcgen::Issuer<'static, rcgen::KeyPair>,
}

impl LabCa {
    fn new(key_type: KeyType) -> Result<Self> {
        let key = rcgen::KeyPair::generate_for(key_type.alg()).map_err(err)?;
        let params = ca_params()?;
        let cert = params.self_signed(&key).map_err(err)?;
        Ok(Self {
            ca_pem: cert.pem(),
            issuer: rcgen::Issuer::new(params, key),
        })
    }

    fn issue(&self, names: &[String], client: bool, key_type: KeyType) -> Result<CertKey> {
        let mut p = rcgen::CertificateParams::new(names.to_vec()).map_err(err)?;
        p.distinguished_name.push(
            rcgen::DnType::CommonName,
            names
                .first()
                .cloned()
                .unwrap_or_else(|| "FeroTRX lab client".into()),
        );
        p.extended_key_usages = vec![if client {
            rcgen::ExtendedKeyUsagePurpose::ClientAuth
        } else {
            rcgen::ExtendedKeyUsagePurpose::ServerAuth
        }];
        p.not_before = rcgen::date_time_ymd(2025, 1, 1);
        p.not_after = rcgen::date_time_ymd(2035, 1, 1);
        p.use_authority_key_identifier_extension = true;
        p.key_usages = vec![
            rcgen::KeyUsagePurpose::DigitalSignature,
            rcgen::KeyUsagePurpose::KeyEncipherment,
        ];
        let key = rcgen::KeyPair::generate_for(key_type.alg()).map_err(err)?;
        let cert = p.signed_by(&key, &self.issuer).map_err(err)?;
        Ok(CertKey {
            chain: format!("{}{}", cert.pem(), self.ca_pem).into_bytes(),
            key: key.serialize_pem().into_bytes(),
        })
    }
}

fn ca_params() -> Result<rcgen::CertificateParams> {
    let mut p = rcgen::CertificateParams::new(Vec::<String>::new()).map_err(err)?;
    p.is_ca = rcgen::IsCa::Ca(rcgen::BasicConstraints::Constrained(0));
    p.distinguished_name
        .push(rcgen::DnType::CommonName, "FeroTRX profile CA");
    p.key_usages = vec![
        rcgen::KeyUsagePurpose::KeyCertSign,
        rcgen::KeyUsagePurpose::CrlSign,
        rcgen::KeyUsagePurpose::DigitalSignature,
    ];
    p.not_before = rcgen::date_time_ymd(2025, 1, 1);
    p.not_after = rcgen::date_time_ymd(2035, 1, 1);
    Ok(p)
}

