#[cfg(feature = "profile")]
mod profile {
    use super::*;
    use serde::Deserialize;
    use std::path::{Path, PathBuf};

    #[derive(Clone, Debug, Default, Deserialize)]
    #[serde(deny_unknown_fields)]
    struct Raw {
        versions: Option<Vec<String>>,
        cipher_suites: Option<Vec<String>>,
        groups: Option<Vec<String>>,
        alpn: Option<Vec<String>>,
        server_name: Option<String>,
        verify: Option<bool>,
        ca: Option<PathBuf>,
        cert: Option<PathBuf>,
        key: Option<PathBuf>,
        names: Option<Vec<String>>,
        key_type: Option<String>,
        client_auth: Option<String>,
        client_ca: Option<PathBuf>,
        client_cert: Option<PathBuf>,
        client_key: Option<PathBuf>,
        resumption: Option<bool>,
        expect: Option<String>,
        client: Option<toml::Table>,
        server: Option<toml::Table>,
    }

    macro_rules! overlay {
        ($base:expr, $o:expr, $($f:ident),*) => {{
            let mut b = $base.clone();
            $( if $o.$f.is_some() { b.$f = $o.$f.clone(); } )*
            b
        }};
    }

    fn read(base: &Path, p: &Path, what: &str) -> Result<Vec<u8>> {
        let path = base.join(p);
        std::fs::read(&path)
            .map_err(|e| err(format!("{what}: cannot read {}: {e}", path.display())))
    }

    fn settings(r: &Raw, base: &Path) -> Result<TlsSettings> {
        let mut s = TlsSettings::default();
        if let Some(v) = &r.versions {
            s.versions = v.iter().map(|v| v.parse()).collect::<Result<_>>()?;
            if s.versions.is_empty() {
                return Err(err("`versions` is empty"));
            }
        }
        s.cipher_suites = r.cipher_suites.clone().unwrap_or_default();
        s.groups = r.groups.clone().unwrap_or_default();
        s.alpn = r.alpn.clone().unwrap_or_default();
        s.server_name = r.server_name.clone();
        s.verify = r.verify.unwrap_or(false) || r.ca.is_some();
        if let Some(p) = &r.ca {
            s.ca = Some(read(base, p, "ca")?);
        }
        s.cert = match (&r.cert, &r.key) {
            (Some(c), Some(k)) => Some(CertKey {
                chain: read(base, c, "cert")?,
                key: read(base, k, "key")?,
            }),
            (Some(c), None) => {
                // A PEM file with both.
                let pem = read(base, c, "cert")?;
                Some(CertKey {
                    chain: pem.clone(),
                    key: pem,
                })
            }
            (None, Some(_)) => return Err(err("`key` needs a `cert`")),
            (None, None) => None,
        };
        if let Some(n) = &r.names {
            s.names = n.clone();
        }
        if let Some(k) = &r.key_type {
            s.key_type = k.parse()?;
        }
        if let Some(a) = &r.client_auth {
            s.client_auth = a.parse()?;
        }
        if let Some(p) = &r.client_ca {
            s.client_ca = Some(read(base, p, "client_ca")?);
        }
        s.client_cert = match (&r.client_cert, &r.client_key) {
            (Some(c), Some(k)) => Some(CertKey {
                chain: read(base, c, "client_cert")?,
                key: read(base, k, "client_key")?,
            }),
            (Some(c), None) => {
                let pem = read(base, c, "client_cert")?;
                Some(CertKey {
                    chain: pem.clone(),
                    key: pem,
                })
            }
            (None, Some(_)) => return Err(err("`client_key` needs a `client_cert`")),
            (None, None) => None,
        };
        if s.client_cert.is_some() && s.client_auth == ClientAuth::None {
            s.client_auth = ClientAuth::Optional;
        }
        s.resumption = r.resumption.unwrap_or(true);
        s.expect_failure = match r.expect.as_deref().map(str::to_ascii_lowercase).as_deref() {
            None | Some("success") | Some("ok") => false,
            Some("failure") | Some("fail") | Some("failed") => true,
            Some(o) => return Err(err(format!("unknown expect `{o}`; use success or failure"))),
        };
        Ok(s)
    }

    fn raw(t: &toml::Table) -> Result<Raw> {
        super::super::registry::table_into(t)
    }

    /// TLS under `inner` from a profile's `[tls]` table (relative paths
    /// from `base`). `[tls.client]` and `[tls.server]` set keys for one
    /// end only.
    pub fn parse(inner: App, table: &toml::Table, base: &Path) -> Result<Tls> {
        let (mut client, server) = parse_ends(table, base)?;
        // ALPN for HTTP unless given: `http/1.1`, or for HTTP/2 `h2` (whose
        // server also takes HTTP/1.1).
        let (c_alpn, s_alpn): (&[&str], &[&str]) = match inner.name() {
            "http" => (&["http/1.1"], &["http/1.1"]),
            "http2" => (&["h2"], &["h2", "http/1.1"]),
            _ => (&[], &[]),
        };
        if client.alpn.is_empty() && server.alpn.is_empty() {
            client.alpn = c_alpn.iter().map(|a| a.to_string()).collect();
        }
        let mut server = server;
        if server.alpn.is_empty() {
            server.alpn = s_alpn.iter().map(|a| a.to_string()).collect();
        }
        Tls::with_ends(inner, client, server)
    }

    /// The settings of both ends from a `[tls]` table, as [`parse`] reads
    /// them, without ALPN defaults.
    pub(crate) fn parse_ends(
        table: &toml::Table,
        base: &Path,
    ) -> Result<(TlsSettings, TlsSettings)> {
        let r = raw(table)?;
        let end = |t: &Option<toml::Table>| -> Result<Raw> {
            let o = match t {
                Some(t) => raw(t)?,
                None => Raw::default(),
            };
            if o.client.is_some() || o.server.is_some() {
                return Err(err("[tls.client] and [tls.server] cannot nest"));
            }
            Ok(overlay!(
                r,
                o,
                versions,
                cipher_suites,
                groups,
                alpn,
                server_name,
                verify,
                ca,
                cert,
                key,
                names,
                key_type,
                client_auth,
                client_ca,
                client_cert,
                client_key,
                resumption,
                expect
            ))
        };
        let client = settings(&end(&r.client)?, base).map_err(|e| prefix("client", e))?;
        let server = settings(&end(&r.server)?, base).map_err(|e| prefix("server", e))?;
        Ok((client, server))
    }

    fn prefix(end: &str, e: Error) -> Error {
        match e {
            Error::Profile(m) => Error::Profile(format!("{end}: {m}")),
            e => e,
        }
    }
}

#[cfg(feature = "profile")]
pub use profile::parse;
#[cfg(feature = "profile")]
pub(crate) use profile::parse_ends;

#[cfg(test)]
mod tests {
    use super::*;
    use crate::app::http::{Http, HttpClient, HttpRequest, HttpServer};
    use std::net::SocketAddr;
    #[cfg(feature = "profile")]
    use std::path::Path;

    fn http() -> App {
        App::new(Http {
            client: HttpClient {
                requests: vec![HttpRequest::get("/")],
                per_connection: 2,
                ..Default::default()
            },
            server: HttpServer::default(),
        })
    }

    fn init(role: AppRole, index: u64) -> SessionInit {
        let a: SocketAddr = "10.0.0.1:40000".parse().unwrap();
        let b: SocketAddr = "10.0.0.2:443".parse().unwrap();
        SessionInit {
            role,
            transport: Transport::Stream,
            index,
            seed: 1,
            local: if role == AppRole::Client { a } else { b },
            remote: if role == AppRole::Client { b } else { a },
        }
    }

    /// Plays a client and a server session against each other, byte
    /// streams handed over whole, until neither has anything to say.
    fn play(tls: &App, index: u64) -> (AppCx, AppCx) {
        let mut c = tls.session(&init(AppRole::Client, index));
        let mut s = tls.session(&init(AppRole::Server, index));
        let (mut cc, mut sc) = (AppCx::new(Duration::ZERO, Duration::ZERO), AppCx::default());
        let mut ccx = AppCx::default();
        c.start(&mut ccx);
        let mut to_server = ccx.take_sends();
        cc.absorb(ccx);
        s.start(&mut sc);
        let (mut c_closed, mut s_closed) = (false, false);
        for _ in 0..50 {
            let mut to_client = Vec::new();
            for d in to_server.drain(..) {
                let mut x = AppCx::default();
                s.receive(&d, &mut x);
                s_closed |= x.wants_close();
                to_client.extend(x.take_sends());
                sc.absorb(x);
            }
            if c_closed && !s_closed {
                let mut x = AppCx::default();
                s.peer_closed(&mut x);
                s_closed |= x.wants_close();
                to_client.extend(x.take_sends());
                sc.absorb(x);
            }
            for d in to_client {
                let mut x = AppCx::default();
                c.receive(&d, &mut x);
                c_closed |= x.wants_close();
                to_server.extend(x.take_sends());
                cc.absorb(x);
            }
            if to_server.is_empty() {
                break;
            }
        }
        (cc, sc)
    }

    #[test]
    fn https_handshakes_and_requests() {
        let tls = App::new(
            Tls::new(
                http(),
                TlsSettings {
                    alpn: vec!["http/1.1".into()],
                    ..Default::default()
                },
            )
            .unwrap(),
        );
        assert_eq!(tls.name(), "https");
        assert_eq!(tls.default_port(), 443);
        let (c, s) = play(&tls, 0);
        assert_eq!(c.handshakes().len(), 1, "{:?}", c.protocol_errors());
        let h = &c.handshakes()[0];
        assert!(h.succeeded && h.expected, "{h:?}");
        assert!(h.label.starts_with("TLSv1.3 TLS13_"), "{}", h.label);
        assert!(h.label.ends_with(" http/1.1"), "{}", h.label);
        assert_eq!(c.transactions().len(), 2, "{:?}", c.protocol_errors());
        assert!(c.all_ok() && s.all_ok());
        assert_eq!(s.handshakes().len(), 1);
        // A second connection resumes the session.
        let (c2, _) = play(&tls, 1);
        assert!(c2.handshakes()[0].resumed, "{:?}", c2.handshakes());
    }

    #[test]
    fn versions_and_suites_are_negotiated_or_refused() {
        let s12 = TlsSettings {
            versions: vec![TlsVersion::Tls12],
            cipher_suites: vec!["ECDHE_ECDSA_WITH_AES_128_GCM_SHA256".into()],
            groups: vec!["secp256r1".into()],
            ..Default::default()
        };
        let tls = App::new(Tls::new(http(), s12.clone()).unwrap());
        let (c, _) = play(&tls, 0);
        assert_eq!(
            c.handshakes()[0].label,
            "TLSv1.2 TLS_ECDHE_ECDSA_WITH_AES_128_GCM_SHA256"
        );
        assert!(c.all_ok());

        // A client that only speaks 1.2 against a server that wants 1.3.
        let only13 = TlsSettings {
            versions: vec![TlsVersion::Tls13],
            ..Default::default()
        };
        let tls = App::new(Tls::with_ends(http(), s12.clone(), only13.clone()).unwrap());
        let (c, s) = play(&tls, 0);
        let h = &c.handshakes()[0];
        assert!(!h.succeeded && !h.expected, "{h:?}");
        assert!(h.label.starts_with("failed: alert"), "{}", h.label);
        assert!(!c.all_ok() && !s.all_ok());
        assert!(c.transactions().is_empty());

        // The same, expected.
        let fail = |mut s: TlsSettings| {
            s.expect_failure = true;
            s
        };
        let tls = App::new(Tls::with_ends(http(), fail(s12), fail(only13)).unwrap());
        let (c, s) = play(&tls, 0);
        assert!(c.all_ok() && s.all_ok(), "{:?}", c.handshakes());
    }

    #[test]
    fn verified_certificates_and_client_certificates() {
        let tls = App::new(
            Tls::new(
                http(),
                TlsSettings {
                    verify: true,
                    server_name: Some("www.lab.local".into()),
                    names: vec!["www.lab.local".into()],
                    client_auth: ClientAuth::Required,
                    key_type: KeyType::Ed25519,
                    ..Default::default()
                },
            )
            .unwrap(),
        );
        let (c, s) = play(&tls, 0);
        assert!(c.handshakes()[0].succeeded, "{:?}", c.handshakes());
        assert!(c.all_ok() && s.all_ok());

        // The name does not match the certificate.
        let tls = App::new(
            Tls::new(
                http(),
                TlsSettings {
                    verify: true,
                    server_name: Some("other.lab.local".into()),
                    ..Default::default()
                },
            )
            .unwrap(),
        );
        let (c, _) = play(&tls, 0);
        assert!(
            c.handshakes()[0]
                .label
                .starts_with("failed: bad certificate"),
            "{:?}",
            c.handshakes()
        );

        // The server wants a certificate the client does not have.
        let server = TlsSettings {
            client_auth: ClientAuth::Required,
            ..Default::default()
        };
        let tls = App::new(Tls::with_ends(http(), TlsSettings::default(), server).unwrap());
        let (_, s) = play(&tls, 0);
        assert!(!s.handshakes().is_empty(), "server counted no handshake");
        assert!(!s.handshakes()[0].succeeded);
    }

    #[test]
    fn bad_settings() {
        assert!("1.0"
            .parse::<TlsVersion>()
            .unwrap_err()
            .to_string()
            .contains("not supported"));
        assert_eq!("TLSv1.3".parse::<TlsVersion>().unwrap(), TlsVersion::Tls13);
        let e = Tls::new(
            http(),
            TlsSettings {
                cipher_suites: vec!["RC4".into()],
                ..Default::default()
            },
        )
        .unwrap_err();
        assert!(e.to_string().contains("unknown cipher suite"), "{e}");
        let e = Tls::new(
            http(),
            TlsSettings {
                versions: vec![TlsVersion::Tls12],
                cipher_suites: vec!["TLS13_AES_128_GCM_SHA256".into()],
                ..Default::default()
            },
        )
        .unwrap_err();
        assert!(e.to_string().contains("none of the cipher suites"), "{e}");
    }

    #[cfg(feature = "profile")]
    #[test]
    fn profile_table() {
        let t: toml::Table = r#"
            versions = ["1.2", "1.3"]
            alpn = ["http/1.1"]
            [client]
            versions = ["1.2"]
            expect = "failure"
            [server]
            versions = ["1.3"]
            expect = "failure"
        "#
        .parse()
        .unwrap();
        let tls = parse(http(), &t, Path::new(".")).unwrap();
        assert_eq!(tls.client_settings().versions, vec![TlsVersion::Tls12]);
        assert_eq!(tls.server_settings().versions, vec![TlsVersion::Tls13]);
        assert!(tls.describe().contains("TLS 1.2"), "{}", tls.describe());
        let bad: toml::Table = "version = \"1.3\"".parse().unwrap();
        assert!(parse(http(), &bad, Path::new(".")).is_err());
    }
}
